"""Loading CSV files as tables."""

import csv
import os
import re
from dataclasses import dataclass

from .errors import QueryError

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


@dataclass
class Table:
    """A CSV table: column names and rows of converted values."""

    columns: list[str]
    rows: list[list]


def _convert(field: str):
    """Convert one CSV field to its value."""
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory: str, name: str) -> Table:
    """Load ``<directory>/<name>.csv`` and return it as a :class:`Table`."""
    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8") as handle:
            try:
                records = list(csv.reader(handle))
            except csv.Error as exc:
                raise QueryError(
                    f"table {name!r}: malformed CSV in {path!r}: {exc}"
                ) from None
    except (OSError, UnicodeError) as exc:
        raise QueryError(
            f"table {name!r}: cannot read {path!r}: {exc}"
        ) from None

    if not records or not records[0]:
        raise QueryError(f"table {name!r}: {path!r} is empty or has no header")

    columns = records[0]
    rows = []
    for row_number, record in enumerate(records[1:], start=2):
        if not record:
            continue
        if len(record) != len(columns):
            raise QueryError(
                f"table {name!r}: row {row_number} has {len(record)} "
                f"field(s), expected {len(columns)}"
            )
        rows.append([_convert(field) for field in record])

    return Table(columns=columns, rows=rows)
